/**
 * El paisaje del estilo pixel art: cielo con estrellas, luna, una estrella fugaz, montañas al
 * fondo y colinas con pinos al frente.
 *
 * Vive en el bundle y no en `index.html` a propósito: son unos 6 kB que la clienta del estilo
 * clásico no tiene por qué descargar en cada carga (el HTML va sin caché). Lo inserta
 * `ponerEstilo` la primera vez que hace falta, y el CSS lo esconde fuera del estilo pixel.
 *
 * Las siluetas solo usan trazos horizontales y verticales, y `crispEdges` les quita el
 * suavizado: así cada unidad del `viewBox` se dibuja como un píxel cuadrado al escalarse, que
 * es el truco entero. Salieron de un generador con semilla fija, no a mano; si se rehacen, que
 * sigan siendo solo H/V o el borde volverá a verse borroso.
 *
 * Los colores salen de la paleta de la clienta (`--primario*`), igual que el fondo clásico:
 * el estilo cambia la forma, no le quita los colores que eligió su entrenador.
 */

const LEJOS =
  "M0 ";

const CERCA =
  "M0 ";

const PINOS =
  "M6 45h1v2h-1zM4 45h5v-2h-5zM5 43h3v-2h-3zM6 41h1v-2h-1zM20 46h1v2h-1zM18 46h5v-3h-5zM19 43h3v-3h-3zM20 40h1v-3h-1zM33 47h1v2h-1zM31 47h5v-2h-5zM32 45h3v-2h-3zM33 43h1v-2h-1zM51 50h1v2h-1zM49 50h5v-3h-5zM50 47h3v-3h-3zM51 44h1v-3h-1zM69 39h1v2h-1zM67 39h5v-2h-5zM68 37h3v-2h-3zM69 35h1v-2h-1zM86 45h1v2h-1zM84 45h5v-3h-5zM85 42h3v-3h-3zM86 39h1v-3h-1zM99 50h1v2h-1zM97 50h5v-3h-5zM98 47h3v-3h-3zM99 44h1v-3h-1zM109 46h1v2h-1zM107 46h5v-3h-5zM108 43h3v-3h-3zM109 40h1v-3h-1zM126 51h1v2h-1zM124 51h5v-2h-5zM125 49h3v-2h-3zM126 47h1v-2h-1zM148 48h1v2h-1zM146 48h5v-2h-5zM147 46h3v-2h-3zM148 44h1v-2h-1zM169 35h1v2h-1zM167 35h5v-3h-5zM168 32h3v-3h-3zM169 29h1v-3h-1zM186 51h1v2h-1zM184 51h5v-2h-5zM185 49h3v-2h-3zM186 47h1v-2h-1zM203 47h1v2h-1zM201 47h5v-2h-5zM202 45h3v-2h-3zM203 43h1v-2h-1zM219 40h1v2h-1zM217 40h5v-2h-5zM218 38h3v-2h-3zM219 36h1v-2h-1zM232 54h1v2h-1zM230 54h5v-2h-5zM231 52h3v-2h-3zM232 50h1v-2h-1zM251 45h1v2h-1zM249 45h5v-2h-5zM250 43h3v-2h-3zM251 41h1v-2h-1zM262 50h1v2h-1zM260 50h5v-2h-5zM261 48h3v-2h-3zM262 46h1v-2h-1zM273 46h1v2h-1zM271 46h5v-3h-5zM272 43h3v-3h-3zM273 40h1v-3h-1zM293 45h1v2h-1zM291 45h5v-2h-5zM292 43h3v-2h-3zM293 41h1v-2h-1zM303 50h1v2h-1zM301 50h5v-2h-5zM302 48h3v-2h-3zM303 46h1v-2h-1z";

/** Creciente de 12×12, dibujada a mano: el borde y el relleno van aparte para darle volumen. */
const LUNA_BORDE =
  "M4 0h4v1h-4zM2 1h2v1h-2zM1 2h1v1h-1zM1 3h1v1h-1zM0 4h1v1h-1zM0 5h1v1h-1zM0 6h1v1h-1zM0 7h1v1h-1zM1 8h1v1h-1zM10 8h1v1h-1zM1 9h1v1h-1zM9 9h1v1h-1zM2 10h2v1h-2zM9 10h1v1h-1zM4 11h4v1h-4z";
const LUNA_RELLENO =
  "M4 1h3v1h-3zM2 2h3v1h-3zM2 3h2v1h-2zM1 4h3v1h-3zM1 5h2v1h-2zM1 6h2v1h-2zM1 7h3v1h-3zM2 8h3v1h-3zM2 9h5v1h-5zM10 9h1v1h-1zM4 10h5v1h-5z";

/** Tamaño del cielo en píxeles del dibujo. Más alto que ancho: casi todas abren en teléfono. */
const ANCHO_CIELO = 120;
const ALTO_CIELO = 240;

/**
 * Las estrellas, repartidas en tres grupos que titilan por turnos. Salen de un generador con
 * semilla fija y no de `Math.random`: así el cielo es el mismo en cada carga (no "salta" al
 * recargar) y la prueba puede contar con él.
 */
export function estrellas(cantidad: number, semilla = 20261007): string[] {
  let s = semilla;
  const azar = () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
  const grupos = ["", "", ""];
  for (let i = 0; i < cantidad; i++) {
    const x = Math.floor(azar() * ANCHO_CIELO);
    // Menos estrellas abajo: ahí las tapan las montañas y la página se ve más limpia.
    const y = Math.floor(azar() ** 1.6 * ALTO_CIELO);
    // Una de cada siete es una cruz de cinco píxeles; las demás, un píxel suelto.
    grupos[i % 3] += i % 7 === 0
      ? `M${x} ${y - 1}h1v3h-1zM${x - 1} ${y}h3v1h-3z`
      : `M${x} ${y}h1v1h-1z`;
  }
  return grupos;
}

/**
 * Una capa de estrellas como imagen de fondo que se repite, y no como un `<svg>` estirado a la
 * ventana: estirado, el píxel del dibujo crecía con la pantalla y en una computadora cada
 * estrella medía once píxeles. Repetido a tamaño fijo (`background-size` en el CSS), el píxel
 * mide lo mismo en cualquier pantalla.
 */
function capaDeEstrellas(d: string, clase: string): string {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${ANCHO_CIELO}' height='${ALTO_CIELO}' ` +
    `viewBox='0 0 ${ANCHO_CIELO} ${ALTO_CIELO}' shape-rendering='crispEdges'>` +
    `<path fill='white' d='${d}'/></svg>`;
  return `<div class="px-estrellas ${clase}"
           style="background-image: url(&quot;data:image/svg+xml,${encodeURIComponent(svg)}&quot;)"></div>`;
}

export function fondoPixel(): string {
  const [a, b, c] = estrellas(90);
  return `
    <div class="fondo-pixel" id="fondo-pixel" aria-hidden="true">
      ${capaDeEstrellas(a, "uno")}
      ${capaDeEstrellas(b, "dos")}
      ${capaDeEstrellas(c, "tres")}
      <svg class="px-luna" viewBox="0 0 12 12" shape-rendering="crispEdges">
        <path class="px-luna-relleno" d="${LUNA_RELLENO}"/>
        <path class="px-luna-borde" d="${LUNA_BORDE}"/>
      </svg>
      <i class="px-fugaz"></i>
      <svg class="px-paisaje" viewBox="0 0 320 64"
           preserveAspectRatio="xMidYMax slice" shape-rendering="crispEdges">
        <path class="px-lejos" d="${LEJOS}"/>
        <path class="px-cerca" d="${CERCA}"/>
        <path class="px-pinos" d="${PINOS}"/>
      </svg>
    </div>`;
}
